exercises.solution:
function tipoDePassagem(idade) {
  if (idade <= 5) {
    return 'grátis';
  } else if (idade <= 17) {
    return 'meia passagem';
  } else if (idade >= 65) {
    return 'grátis';
  } else {
    return 'passagem inteira';
  }
}

console.log(`4 anos: ${tipoDePassagem(4)}`);
console.log(`17 anos: ${tipoDePassagem(17)}`);
console.log(`18 anos: ${tipoDePassagem(18)}`);
console.log(`64 anos: ${tipoDePassagem(64)}`);
console.log(`65 anos: ${tipoDePassagem(65)}`);

