exercises.solution:
function conferirApelido(texto) {
  const apelido = texto.trim();
  if (apelido === '') {
    return 'Digite um apelido';
  } else if (apelido.length < 3) {
    return 'Apelido muito curto';
  } else if (apelido.length > 12) {
    return 'Apelido muito longo';
  } else if (apelido.includes(' ')) {
    return 'Apelido sem espaços, por favor';
  } else {
    return 'Apelido aceito';
  }
}

console.log(conferirApelido('   '));
console.log(conferirApelido('Jo'));
console.log(conferirApelido('clarinha_da_silva'));
console.log(conferirApelido('bia lima'));
console.log(conferirApelido('  bia_lima  '));

